// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract StakingRewards {
    mapping(address => uint256) public staked;
    mapping(address => uint256) public rewardPaid;
    uint256 public totalStaked;
    uint256 public rewardPool;
    uint256 public constant REWARD_BPS = 2000;

    event Staked(address indexed user, uint256 amount);
    event Unstaked(address indexed user, uint256 amount);
    event RewardClaimed(address indexed user, uint256 amount);

    constructor() payable {
        rewardPool = msg.value;
    }

    function stake() external payable {
        require(msg.value > 0, "zero stake");
        staked[msg.sender] += msg.value;
        totalStaked += msg.value;
        emit Staked(msg.sender, msg.value);
    }

    function pendingReward(address user) public view returns (uint256) {
        uint256 accrued = (staked[user] * REWARD_BPS) / 10000;
        if (accrued <= rewardPaid[user]) {
            return 0;
        }
        return accrued - rewardPaid[user];
    }

    function claimReward() external {
        uint256 amount = pendingReward(msg.sender);
        require(amount > 0, "nothing to claim");
        require(rewardPool >= amount, "reward pool exhausted");
        rewardPool -= amount;
        (bool ok, ) = msg.sender.call{value: amount}("");
        require(ok, "reward transfer failed");
        rewardPaid[msg.sender] += amount;
        emit RewardClaimed(msg.sender, amount);
    }

    function unstake(uint256 amount) external {
        require(staked[msg.sender] >= amount, "insufficient stake");
        staked[msg.sender] -= amount;
        totalStaked -= amount;
        (bool ok, ) = msg.sender.call{value: amount}("");
        require(ok, "unstake transfer failed");
        emit Unstaked(msg.sender, amount);
    }

    function fundRewards() external payable {
        rewardPool += msg.value;
    }
}

