        emit Swapped(msg.sender, amountIn, out);
    }

    function swap(uint256 minOut) external payable returns (uint256 out) {
        require(msg.value > 0, "nothing to swap");
        out = _swapEthForToken(msg.value, minOut);
        token.transfer(msg.sender, out);
    }

    /// Converts idle treasury ETH into reserve tokens at no worse than the
    /// published rate less the protocol slippage allowance.
    function rebalance() external returns (uint256 out) {
        uint256 amountIn = address(this).balance;
        require(amountIn > 0, "nothing to rebalance");
        uint256 minOut = (quote(amountIn) * (10000 - MAX_SLIPPAGE_BPS)) / 10000;
        out = _swapEthForToken(amountIn, minOut);
        emit Rebalanced(amountIn, out);
    }

    receive() external payable {}
}

